3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone into E.164 form: strips spaces, dashes and brackets,
9	 * keeps a leading '+' and country code when present, otherwise assumes country code '+61' and
10	 * drops a single leading '0' from the national digits, requiring 8 to 15 digits after the '+'.
11	 * The national-number length must also match the country code ('+61' → 9 national digits,
12	 * '+1' → 10). Mutates the published request in place so later steps store and return the E.164
13	 * value. Rejects anything that cannot form a valid E.164 number, or whose national-number length
14	 * is wrong for its country code, with a 400.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerTelephoneException {
19	        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
20	        if (e164 == null || !TelephoneNormalizer.hasValidNationalLength(e164)) {
21	            throw new InvalidOwnerTelephoneException(request.getTelephone());
22	        }
23	        request.setTelephone(e164);
24	    }
25	}
