1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerDailyLimitException;
10	
11	/**
12	 * Rejects a create-owner request with a 429 once {@value #DAILY_LIMIT} or more owners have already
13	 * been registered today (by {@code registrationDate}). Runs before the owner is saved, so the count
14	 * reflects existing owners only.
15	 */
16	public class CheckOwnerDailyLimit {
17	
18	    /** No more owners may be created today once this many already carry today's registration date. */
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws OwnerDailyLimitException {
23	        // Count against the adjusted business day this owner will actually be registered on:
24	        // the effective date (supplied or defaulted to today) rolled forward off a weekend.
25	        LocalDate effective = request.getRegistrationDate() != null ? request.getRegistrationDate() : LocalDate.now();
26	        LocalDate businessDay = BusinessDay.roll(effective);
27	        long count = ownerRepository.findAll().stream()
28	                .map(Owner::getRegistrationDate)
29	                .filter(businessDay::equals)
30	                .count();
31	        if (count >= DAILY_LIMIT) {
32	            throw new OwnerDailyLimitException((int) count);
33	        }
34	    }
35	}
