1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Out;
11	import net.officefloor.plugin.variable.Val;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
15	
16	/**
17	 * Resolves the shared {@code householdId} for a create-owner request. A "household" is a set of
18	 * owners that share the same last name and the same address. The last name is compared
19	 * case-insensitively with runs of whitespace collapsed to a single space and leading/trailing
20	 * whitespace trimmed; the address is compared in its {@link AddressNormalizer normalized} form.
21	 *
22	 * <p>When the request opts in with {@code sharesHousehold} true and matches an existing household,
23	 * the join is allowed and a stable shared {@code householdId} — derived from the canonical last
24	 * name and address, so every member of the household derives the same value — is stamped onto the
25	 * existing members and published for {@link AssignOwnerHousehold} to stamp onto the new owner.
26	 *
27	 * <p>Otherwise (no opt-in, or no existing household match) no {@code householdId} is assigned and
28	 * the owner remains outside any household. Duplicate detection is no longer performed here: it is
29	 * handled uniformly by {@link CheckOwnerIdentityUnique} on the whole {@link OwnerIdentityKey
30	 * identity key}, of which the resolved {@code householdId} is one part.
31	 */
32	public class DetermineOwnerHousehold {
33	
34	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
35	            Out<HouseholdId> householdId) {
36	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
37	            return; // did not opt into a shared household — no householdId
38	        }
39	        String lastName = canonical(request.getLastName());
40	        String address = AddressNormalizer.normalize(request.getAddress());
41	        List<Owner> members = new ArrayList<>();
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (lastName.equals(canonical(existing.getLastName()))
44	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
45	                members.add(existing);
46	            }
47	        }
48	        if (members.isEmpty()) {
49	            return; // no existing household to join
50	        }
51	        // Opted in to share the household: assign the same stable id to every member.
52	        String id = deriveHouseholdId(lastName, address);
53	        for (Owner member : members) {
54	            member.setHouseholdId(id);
55	            ownerRepository.save(member);
56	        }
57	        householdId.set(new HouseholdId(id));
58	    }
59	
60	    /**
61	     * A stable household identifier derived from the canonical last name and address, so that
62	     * every owner joining the same household independently derives an identical value.
63	     */
64	    static String deriveHouseholdId(String canonicalLastName, String canonicalAddress) {
65	        String seed = canonicalLastName + "\n" + canonicalAddress;
66	        try {
67	            byte[] digest = MessageDigest.getInstance("SHA-256")
68	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
69	            StringBuilder hex = new StringBuilder();
70	            for (int i = 0; i < 6; i++) {
71	                hex.append(String.format("%02X", digest[i]));
72	            }
73	            return "HH-" + hex;
74	        }
75	        catch (NoSuchAlgorithmException ex) {
76	            throw new IllegalStateException("SHA-256 unavailable", ex);
77	        }
78	    }
79	
80	    private static String canonical(String value) {
81	        if (value == null) {
82	            return "";
83	        }
84	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
85	    }
86	}
