1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
8	
9	/**
10	 * The single duplicate check for a create-owner request: it consolidates the former separate
11	 * telephone, email and household checks into one comparison of the whole derived
12	 * {@link OwnerIdentityKey identity key}
13	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}).
14	 *
15	 * <p>Runs after the telephone and email have been normalized and after
16	 * {@link DetermineOwnerHousehold} has resolved any shared {@code householdId}, so the request's
17	 * key is built from the same normalized parts as each existing owner's key. A create is rejected
18	 * with a 409 only when the request's whole identity key equals an existing owner's — so two
19	 * members of the same household with different telephones (different keys) are both allowed.
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
24	            OwnerRepository ownerRepository) throws DuplicateOwnerIdentityException {
25	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(),
26	                householdId == null ? null : householdId.value());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
29	                throw new DuplicateOwnerIdentityException(identityKey);
30	            }
31	        }
32	    }
33	}
