3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerCityFullException;
8	
9	/**
10	 * Rejects a create-owner request whose city already contains {@value #CAPACITY} or more owners
11	 * with a 409. The city is compared case-insensitively, matching the per-city counting used by
12	 * {@code AssignOwnerCustomerCode}. Runs before the owner is saved, so the count reflects
13	 * existing owners only.
14	 */
15	public class CheckOwnerCityCapacity {
16	
17	    /** A city is full once it already holds this many owners. */
18	    static final int CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws OwnerCityFullException {
22	        String city = request.getCity();
23	        long count = ownerRepository.findAll().stream()
24	                .map(Owner::getCity)
25	                .filter(existing -> city == null ? existing == null : city.equalsIgnoreCase(existing))
26	                .count();
27	        if (count >= CAPACITY) {
28	            throw new OwnerCityFullException(city, (int) count);
29	        }
30	    }
31	}
