3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode} formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is
9	 * the upper-cased first three letters of city, LAST3 the upper-cased first three of lastName and
10	 * NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of owners already
11	 * in that city (e.g. {@code TOW-SMI-0007}). Runs after the owner is built and before it is saved,
12	 * so the count reflects existing owners only.
13	 */
14	public class AssignOwnerCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
19	        String lastName = owner.getLastName();
20	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
21	        int sequence = (int) ownerRepository.findAll().stream()
22	                .filter(o -> city.equalsIgnoreCase(o.getCity()))
23	                .count() + 1;
24	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
25	    }
26	}
