2	
3	import java.util.Map;
4	
5	/**
6	 * Converts a raw telephone entry into E.164 form.
7	 *
8	 * <p>Rules: strip spaces, dashes and brackets; keep a leading {@code '+'} and its country
9	 * code when present; otherwise assume country code {@code '+61'} and drop a single leading
10	 * {@code '0'} from the national digits. The result is {@code '+'} followed by 8 to 15 digits;
11	 * anything that cannot form a valid E.164 number yields {@code null}.
12	 *
13	 * <p>The conversion is idempotent — feeding an already-E.164 value back in returns it
14	 * unchanged — so it can normalize both incoming requests and already-stored values for
15	 * comparison.
16	 */
17	final class TelephoneNormalizer {
18	
19	    /**
20	     * Required national-number length (digits after the country code) per known country code.
21	     * {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
22	     */
23	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
24	
25	    private TelephoneNormalizer() {
26	    }
27	
28	    /**
29	     * @param raw the raw telephone text (may be {@code null})
30	     * @return the E.164 string, or {@code null} when {@code raw} cannot form a valid one
31	     */
32	    static String toE164(String raw) {
33	        if (raw == null) {
34	            return null;
35	        }
36	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
37	        String digits;
38	        if (cleaned.startsWith("+")) {
39	            digits = cleaned.substring(1);
40	        }
41	        else {
42	            if (cleaned.startsWith("0")) {
43	                cleaned = cleaned.substring(1);
44	            }
45	            digits = "61" + cleaned;
46	        }
47	        if (!digits.matches("[0-9]{8,15}")) {
48	            return null;
49	        }
50	        return "+" + digits;
51	    }
52	
53	    /**
54	     * Checks the national-number length of an E.164 value against its country code. For a known
55	     * country code ({@code '+61'} → 9 national digits, {@code '+1'} → 10) the national part must be
56	     * exactly that many digits; unknown country codes are left to the generic 8-to-15 rule.
57	     *
58	     * @param e164 an E.164 string ({@code '+'} followed by digits), as produced by {@link #toE164}
59	     * @return {@code true} when the national-number length is valid for the country code
60	     */
61	    static boolean hasValidNationalLength(String e164) {
62	        String digits = e164.substring(1);
63	        String code = null;
64	        for (String candidate : NATIONAL_LENGTHS.keySet()) {
65	            if (digits.startsWith(candidate) && (code == null || candidate.length() > code.length())) {
66	                code = candidate;
67	            }
68	        }
69	        if (code == null) {
70	            return true;
71	        }
72	        return digits.length() - code.length() == NATIONAL_LENGTHS.get(code);
73	    }
74	}
