3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day adjustment for the owner registration date. A registration date must fall on a
8	 * business day: when it lands on a Saturday or Sunday it rolls forward to the next Monday. Applied
9	 * to the effective registration date (supplied or defaulted to the server date) so every value
10	 * derived from it — the membership number's year segment, the daily create-limit count — uses the
11	 * adjusted date.
12	 */
13	final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    /** Roll a weekend date forward to the next Monday; any weekday is returned unchanged. */
19	    static LocalDate roll(LocalDate date) {
20	        DayOfWeek dow = date.getDayOfWeek();
21	        if (dow == DayOfWeek.SATURDAY) {
22	            return date.plusDays(2);
23	        }
24	        if (dow == DayOfWeek.SUNDAY) {
25	            return date.plusDays(1);
26	        }
27	        return date;
28	    }
29	}
