2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} (canonical region) by preferring the postcode
7	 * range, then falling back to a fixed city-to-region table.
8	 *
9	 * <p>Deliberately a plain utility class rather than a method on {@link OwnerMapper}:
10	 * a {@code String -> String} method declared on a MapStruct {@code @Mapper} interface
11	 * would be picked up as a general property-conversion method and silently applied to
12	 * every string field. Kept here, it is only ever invoked from an explicit mapping
13	 * expression, so MapStruct never treats it as a conversion.
14	 */
15	public final class LocalityLookup {
16	
17	    /** City -> canonical region; anything absent derives locality "UNKNOWN". */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {low, high}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	            "NSW", new int[] {2000, 2099},
24	            "VIC", new int[] {3000, 3099},
25	            "QLD", new int[] {4000, 4099});
26	
27	    private LocalityLookup() {
28	    }
29	
30	    /**
31	     * @param city the owner's city (may be {@code null})
32	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is not
33	     *         in the table
34	     */
35	    public static String regionFor(String city) {
36	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
37	    }
38	
39	    /**
40	     * Derives the canonical region, preferring the postcode: when {@code postcode} is a
41	     * 4-digit value inside a known region range (NSW 2000-2099, VIC 3000-3099,
42	     * QLD 4000-4099) that region wins, disambiguating cities that share a name.
43	     * Otherwise — postcode absent or in no known range — falls back to the
44	     * city-to-region table.
45	     *
46	     * @param city the owner's city (may be {@code null})
47	     * @param postcode the owner's postcode (may be {@code null}/blank)
48	     * @return the canonical region, or {@code "UNKNOWN"} when neither source resolves one
49	     */
50	    public static String regionFor(String city, String postcode) {
51	        String byPostcode = regionForPostcode(postcode);
52	        return byPostcode != null ? byPostcode : regionFor(city);
53	    }
54	
55	    /**
56	     * @return the region whose range contains {@code postcode}, or {@code null} when the
57	     *         postcode is absent, not 4 digits, or in no known range
58	     */
59	    private static String regionForPostcode(String postcode) {
60	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
61	            return null;
62	        }
63	        int value = Integer.parseInt(postcode);
64	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
65	            int[] range = entry.getValue();
66	            if (value >= range[0] && value <= range[1]) {
67	                return entry.getKey();
68	            }
69	        }
70	        return null;
71	    }
72	}
